    raise ValueError(f"Unsupported date type: {type(value).__name__}")


def _extract_payment_fields(payment, today):
    """Return (payment_date, dollars) from a payment item of flexible shape."""
    payment_date = today
    dollars = None

    if isinstance(payment, dict):
        if "date" in payment and payment["date"] is not None:
            payment_date = _coerce_date(payment["date"])
        for key in ("amount", "dollars", "value"):
            if key in payment:
                dollars = payment[key]
                break

    elif isinstance(payment, (tuple, list)):
        if len(payment) == 1:
            dollars = payment[0]
        elif len(payment) == 2:
            payment_date = _coerce_date(payment[0])
            dollars = payment[1]
        else:
            raise ValueError("Tuple/list payment must have length 1 (amount) or 2 (date, amount)")

    else:
        # Object-like: accept .date and one of .amount/.dollars/.value
        if hasattr(payment, "date") and getattr(payment, "date") is not None:
            payment_date = _coerce_date(getattr(payment, "date"))
        for attr in ("amount", "dollars", "value"):
