def busiest_day(
    ledger: Any,
    first_day: _dt.date,
    last_day: _dt.date,
) -> Optional[_dt.date]:
    """Return the date with the most ledger entries in [first_day, last_day]."""

    entries: list[Tuple[_dt.date, Any, Any]] = list(ledger.between(first_day, last_day))
    if not entries:
        return None

    counts: Dict[_dt.date, int] = {}
    for d, _, _ in entries:
        counts[d] = counts.get(d, 0) + 1

    best_date: _dt.date | None = None
    best_count = -1
    for d, c in counts.items():
        if c > best_count or (c == best_count and (best_date is None or d < best_date)):
            best_date = d
            best_count = c

    return best_date

