    """Merge two lists of (key, qty) records, summing qty for equal keys."""
    out = []
    i = j = 0
    while i < len(a) or j < len(b):
        if j >= len(b) or (i < len(a) and a[i][0] <= b[j][0]):
            key, qty = a[i]
            i += 1
        else:
            key, qty = b[j]
            j += 1
        if out and key == out[-1][0]:
            out[-1] = (key, out[-1][1] + qty)
        elif not out or key > out[-1][0]:
            out.append((key, qty))
    return out

